from fractions import Fraction

def solve():
    base = Fraction(P["BASE"])
    bps = [Fraction(P["BPS_A"]), Fraction(P["BPS_B"]), Fraction(P["BPS_C"])]
    qs = [P["Q_A"], P["Q_B"], P["Q_C"]]
    cost_pct = Fraction(P["COST_PCT"])
    for q in qs:
        if q < 1 or q > 8:
            raise ValueError("completion quarter must lie within quarters 1 through 8")
    annual = [base * b / Fraction(10000) for b in bps]
    quarterly = [a / Fraction(4) for a in annual]
    costs = [a * cost_pct / Fraction(100) for a in annual]
    total_cost = sum(costs, Fraction(0))
    cumulative = Fraction(0)
    first_pos = 0
    cum_q4 = Fraction(0)
    saving_q8 = Fraction(0)
    for q in range(1, 9):
        net = Fraction(0)
        earned = Fraction(0)
        for i in range(3):
            if qs[i] == q:
                net -= costs[i]
            if q > qs[i]:
                earned += quarterly[i]
        net += earned
        cumulative += net
        if first_pos == 0 and cumulative > 0:
            first_pos = q
        if q == 4:
            cum_q4 = cumulative
        if q == 8:
            saving_q8 = earned
    return {
        "final": cumulative,
        "total_one_time_cost": total_cost,
        "run_rate_quarterly_saving": saving_q8,
        "first_positive_quarter": first_pos,
        "cumulative_after_q4": cum_q4,
    }
